<script setup>
import{onMounted,ref}from'vue';import{api}from'../services/api';const metadata=ref({}),options=ref({}),status=ref('');const fields=[['title','Título'],['publisher','Editorial'],['identifier','Identificador / ISBN-NIMAS'],['source_isbns','ISBN de origen'],['language','Idioma'],['copyright_year','Año de copyright'],['publication_year','Año de publicación'],['content_type','Tipo de contenido'],['state_edition','Edición estatal']];onMounted(async()=>{const d=await api.projectDetail();metadata.value=d.metadata||{};options.value=await api.nimacTemplate()});async function save(){await api.saveSetup({metadata:metadata.value});status.value='Metadata guardada.'}
</script>
<template><section class="hero"><span class="eyebrow">PASO 2 · METADATA</span><h2>Metadata NIMAC</h2><p>Completa estos datos después de aprobar las lecciones. Los permisos predeterminados no se solicitan.</p></section><form class="metadata-card" @submit.prevent="save"><label v-for="[key,label] in fields" :key="key">{{label}}<select v-if="options[key]" v-model="metadata[key]"><option v-for="value in options[key]" :key="value">{{value}}</option></select><input v-else v-model="metadata[key]"/></label><label>Autores, ilustradores y editores<input :value="(metadata.creators||[]).map(x=>x.name||x).join('; ')" aria-describedby="creator-hint" @input="metadata.creators=$event.target.value.split(';').map(name=>({name:name.trim(),role:'author'})).filter(x=>x.name)"/><small id="creator-hint">Separa personas con punto y coma (;).</small></label><button type="submit">Guardar metadata</button><span class="hint">{{status}}</span></form></template>
